      "path": "src/index.css",
      "content": "* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',\n    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',\n    sans-serif;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  background: #f8f9fa;\n  color: #1a1a1a;\n  line-height: 1.5;\n}\n\n#root {\n  min-height: 100vh;\n}\n\nbutton {\n  font-family: inherit;\n  cursor: pointer;\n  border: none;\n  background: none;\n}\n\ninput {\n  font-family: inherit;\n}\n\n:focus-visible {\n  outline: 2px solid #2563eb;\n  outline-offset: 2px;\n}"
